// The commands `new`, `list`, `show`, and `status` of the `minispec` CLI.
// Each command gives a `Reply`, and the CLI prints it. None of them keeps a log.

import path from "node:path";
import { countTasks, openChange } from "../../../kernel/change.ts";
import { parseRequirements } from "../domain/spec.ts";
import { parseTasks } from "../domain/tasks.ts";
import { filesOf } from "../domain/templates.ts";
import { hintOf, nameIssue, nearest } from "../domain/text.ts";
import {
  type Context,
  EXIT,
  type Options,
  type Reply,
} from "../domain/types.ts";
import { SHOW_LINES_MAX } from "../limits.ts";
import {
  LIST_NO_CHANGES,
  LIST_NO_SPECS,
  NEW_CREATED,
  NEW_EXISTS,
  NEW_NEEDS_NAME,
  SHOW_CUT,
  SHOW_NEEDS_NAME,
  STATUS_ALL_DONE,
  STATUS_NO_CHECK,
  STATUS_NO_TASKS,
  STATUS_NONE,
  STATUS_SUMMARY,
  UNKNOWN_NAME,
} from "../prompts.ts";
import {
  at,
  CHANGES,
  changeNames,
  type Loaded,
  loadChange,
  readSpec,
  specNames,
} from "./load.ts";

const ok = (out: string): Reply => ({ code: EXIT.ok, out, err: "" });
export const fail = (err: string, code: number = EXIT.failed): Reply => ({
  code,
  out: "",
  err,
});
const json = (value: unknown): Reply => ok(JSON.stringify(value, null, 2));

/** The text for an unknown `name`: the nearest name when there is one, and the next command. */
const unknown = (
  name: string,
  known: readonly string[],
  list: string,
): string => {
  const near = nearest(name, known);
  return UNKNOWN_NAME({ name, hint: hintOf(near), list });
};

/** `minispec new <name>`. */
export const newCommand = async (
  ctx: Context,
  words: readonly string[],
  opts: Options,
): Promise<Reply> => {
  const name = words[0];
  if (name === undefined) return fail(NEW_NEEDS_NAME, EXIT.usage);
  const tier = opts.tier ?? "medium";
  const capability = opts.capability ?? name;
  const bad = nameIssue(name, "change") ?? nameIssue(capability, "capability");
  if (bad !== null) return fail(bad, EXIT.usage);
  if ((await loadChange(ctx, name)) !== null) return fail(NEW_EXISTS({ name }));
  const written: string[] = [];
  for (const [file, text] of filesOf(name, tier, capability)) {
    await ctx.store.write(at(ctx, `${CHANGES}/${name}/${file}`), text);
    written.push(`${CHANGES}/${name}/${file}`);
  }
  if (opts.json) return json({ name, tier, files: written });
  return ok(
    NEW_CREATED({
      count: String(written.length),
      tier,
      name,
      files: written.map((f) => `  ${f}`).join("\n"),
    }),
  );
};

/** `minispec list`. */
export const listCommand = async (
  ctx: Context,
  opts: Options,
): Promise<Reply> => {
  if (opts.specs) {
    const rows = await Promise.all(
      (await specNames(ctx)).map(async (name) => ({
        name,
        requirements: parseRequirements((await readSpec(ctx, name)) ?? "")
          .length,
      })),
    );
    if (opts.json) return json(rows);
    if (rows.length === 0) return ok(LIST_NO_SPECS);
    return ok(
      rows.map((r) => `${r.name}  ${r.requirements} requirements`).join("\n"),
    );
  }
  const rows = [];
  for (const name of await changeNames(ctx)) {
    const c = await loadChange(ctx, name);
    const counts = countTasks(c?.tasks ?? "");
    rows.push({
      name,
      tier: c?.tier ?? "medium",
      done: counts.done,
      total: counts.total,
      next: counts.next,
    });
  }
  if (opts.json) return json(rows);
  if (rows.length === 0) return ok(LIST_NO_CHANGES);
  return ok(
    rows
      .map(
        (r) =>
          `${r.name}  ${r.tier}  ${r.done}/${r.total} tasks${r.next ? `  next ${r.next}` : ""}`,
      )
      .join("\n"),
  );
};

/** The first `SHOW_LINES_MAX` lines of `text`, with a last line that names `path` when the text is cut. */
const cut = (path: string, text: string): string => {
  const lines = text.split("\n");
  return lines.length <= SHOW_LINES_MAX
    ? text
    : `${lines.slice(0, SHOW_LINES_MAX).join("\n")}\n${SHOW_CUT({ count: String(lines.length - SHOW_LINES_MAX), path })}`;
};

/** `minispec show <name>`. */
export const showCommand = async (
  ctx: Context,
  words: readonly string[],
  opts: Options,
): Promise<Reply> => {
  const name = words[0];
  if (name === undefined) return fail(SHOW_NEEDS_NAME, EXIT.usage);
  const change = await loadChange(ctx, name);
  const files: { path: string; text: string }[] = [];
  if (change) {
    const add = (file: string, text: string | null) =>
      text !== null &&
      files.push({ path: path.posix.join(change.dir, file), text });
    add("proposal.md", change.proposal);
    add("design.md", change.design);
    for (const s of change.specs) add(`specs/${s.capability}/spec.md`, s.text);
    add("tasks.md", change.tasks);
  } else {
    const text = await readSpec(ctx, name);
    if (text === null)
      return fail(
        unknown(
          name,
          [...(await changeNames(ctx)), ...(await specNames(ctx))],
          "minispec list",
        ),
      );
    files.push({ path: `minispec/specs/${name}/spec.md`, text });
  }
  if (opts.json) return json({ name, type: change ? "change" : "spec", files });
  return ok(
    files.map((f) => `==> ${f.path} <==\n${cut(f.path, f.text)}`).join("\n"),
  );
};

/** The status of a change: counts, the next task with its check, and the files. */
const statusOf = (c: Loaded) => {
  const counts = countTasks(c.tasks ?? "");
  const next =
    parseTasks(c.tasks ?? "").find((t) => t.id === counts.next) ?? null;
  const state =
    counts.total === 0 ? "planning" : counts.next === null ? "done" : "open";
  return {
    name: c.name,
    tier: c.tier,
    state,
    done: counts.done,
    total: counts.total,
    next: next && { id: next.id, text: next.text, check: next.check },
    handoff: c.hasHandoff,
  };
};

/** `minispec status [name]`. */
export const statusCommand = async (
  ctx: Context,
  words: readonly string[],
  opts: Options,
): Promise<Reply> => {
  let name = words[0];
  const names = await changeNames(ctx);
  if (name === undefined) {
    const loaded = await Promise.all(names.map((n) => loadChange(ctx, n)));
    name =
      openChange(
        loaded.flatMap((c) => (c ? [{ name: c.name, tasks: c.tasks }] : [])),
      )?.name ?? names[0];
    if (name === undefined) return fail(STATUS_NONE);
  }
  const change = await loadChange(ctx, name);
  if (change === null) return fail(unknown(name, names, "minispec list"));
  const s = statusOf(change);
  if (opts.json) return json(s);
  const lines = [
    STATUS_SUMMARY({
      name: s.name,
      tier: s.tier,
      state: s.state,
      done: String(s.done),
      total: String(s.total),
    }),
  ];
  if (s.next)
    lines.push(
      `Next task: ${s.next.id} ${s.next.text}`,
      s.next.check ? `Check: ${s.next.check}` : STATUS_NO_CHECK,
    );
  else if (s.state === "done") lines.push(STATUS_ALL_DONE({ name: s.name }));
  else
    lines.push(
      STATUS_NO_TASKS({ path: path.posix.join(change.dir, "tasks.md") }),
    );
  if (s.handoff)
    lines.push(`Handoff: ${path.posix.join(change.dir, "handoff.md")}`);
  return ok(lines.join("\n"));
};
